            <div class="dialog-seniority-header">
              <v-icon size="16" :color="employeeColor(selectedEmployee)">mdi-medal-outline</v-icon>
              <span>Jours d'ancienneté</span>
            </div>
            <div class="dialog-seniority-body">
              <div class="dialog-sen-stat">
                <span class="dialog-sen-num" :style="{ color: employeeColor(selectedEmployee) }">
                  {{ selectedEmployee.jour_anciennete_total || 0 }}
                </span>
                <span class="dialog-sen-label">Total acquis</span>
              </div>
              <div class="dialog-sen-div"></div>
              <div class="dialog-sen-stat">
                <span class="dialog-sen-num" style="color: #43a047">
                  {{ selectedEmployee.jour_anciennete_dispo || 0 }}
                </span>
                <span class="dialog-sen-label">Disponibles</span>
              </div>
            </div>
          </div> -->

