                  <span class="adm-solde-kv">
                    <span class="adm-solde-k">Pris</span>
                    <span v-if="editingSoldeType !== selectedEmployeeSoldeCp.id_conge_type" class="adm-solde-v" style="color:#9c27b0;">{{ selectedEmployeeSoldeCp.cp_reserves_n || 0 }}</span>
                    <input v-else v-model.number="editSoldeValues.cp_reserves_n" type="number" class="adm-solde-input" style="color:#9c27b0;" />
