                  <v-btn icon size="x-small" variant="text" color="#9e9e9e" @click="openSoldeEdit(selectedEmployeeSoldeCp)">
                    <v-icon size="15">mdi-pencil-outline</v-icon>
                  </v-btn>
                </template>
                <template v-else>
                  <v-btn icon size="x-small" variant="flat" color="#43a047" :loading="isSavingSolde" @click="saveSoldeEdit(selectedEmployeeSoldeCp)">
                    <v-icon size="15" color="white">mdi-check</v-icon>
                  </v-btn>
                  <v-btn icon size="x-small" variant="flat" color="#e53935" @click="cancelSoldeEdit()">
                    <v-icon size="15" color="white">mdi-close</v-icon>
