                    <span v-if="editingSoldeType !== s.id_conge_type" class="adm-solde-v" style="color:#3f51b5;">{{ s.solde_disponible || 0 }}</span>
                    <input v-else v-model.number="editSoldeValues.solde_disponible" type="number" class="adm-solde-input" style="color:#3f51b5;" />
                  </span>
                </div>
              </div>
