                <template v-if="editingSoldeType !== s.id_conge_type">
                  <v-btn icon size="x-small" variant="text" color="#9e9e9e" @click="openSoldeEdit(s)">
                    <v-icon size="15">mdi-pencil-outline</v-icon>
                  </v-btn>
                </template>
                <template v-else>
