<script>
import engine from "@/core/index";
import moment from 'moment';
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';

// ─── Mettre à true pour autoriser l'édition des soldes (CP, RTT, etc.) ───
const ALLOW_SOLDE_EDIT = true;

const COLOR_PALETTE = ['#3f51b5', '#e53935', '#43a047', '#fb8c00', '#9c27b0', '#00838f', '#f9a825'];
const COLOR_DARK = ['#283593', '#b71c1c', '#2e7d32', '#e65100', '#6a1b9a', '#005662', '#f57f17'];

export default {
  name: "HomeAdmin",
  props: {
    get_basic_data: { type: Function },
    userInfo: { type: Object, default: () => ({}) },
    allUsers: { type: Array, default: () => [] },
    congeTypes: { type: Array, default: () => [] },
  },
  data() {
    return {
      snackbar: {},
      employeeSearch: "",
      selectedEmployee: null,
      showEmployeeDialog: false,
      selectedEmployeeCongeListe: [],
      selectedEmployeeSoldeListe: [],
      pendingCounts: {},
      hideZeroSoldeAdmin: true,
      allowSoldeEdit: ALLOW_SOLDE_EDIT,
      editingSoldeType: null,
      editSoldeValues: {},
      isSavingSolde: false,
      showValidationModal: false,
      selectedRequest: null,
      isUpdating: false,
      adminDeleteMotif: '',
      showGlobalExportDialog: false,
      globalExportPeriod: 'all',
      globalExportDateFrom: null,
      globalExportDateTo: null,
      isGlobalExporting: false,
      showAdminDeleteDialog: false,
      requestToAdminDelete: null,
      isDeletingAdmin: false,
      showExportDialog: false,
      exportPeriod: 'all',
      exportDateFrom: null,
      exportDateTo: null,
      showNewRequestDialog: false,
      adminFormValid: false,
      isSubmittingAdmin: false,
      adminDateDebutError: '',
      adminDateFinError: '',
      adminForm: {
        type: null,
        dateDebut: null,
        dateFin: null,
        nbrJours: null,
        motif: '',
      },
      congeHeaders: [
        { title: 'Type', key: 'id_conge_type', sortable: true },
        { title: 'Date début', key: 'debut_timestamp', sortable: true },
        { title: 'Date fin', key: 'fin_timestamp', sortable: true },
        { title: 'Jours', key: 'nbr_days', sortable: true },
        { title: 'Motif', key: 'commentaire', sortable: false },
        { title: 'Statut', key: 'statut', sortable: true },
      ],
    };
  },
  watch: {
    allUsers: {
      handler(users) {
        if (users && users.length > 0) this.fetchAllPendingCounts(users);
      },
      immediate: true,
    },
  },
  computed: {
    selectedEmployeeSoldeCp() {
      return this.selectedEmployeeSoldeListe.find(s => s.id_conge_type === 'CP') || {};
    },
    selectedEmployeeSoldeAutres() {
      return this.selectedEmployeeSoldeListe.filter(s => s.id_conge_type !== 'CP');
    },
    filteredEmployees() {
      const q = (this.employeeSearch || "").toLowerCase().trim();
      if (!q) return this.allUsers;
      return this.allUsers.filter(emp => {
        const name = (emp.user_name || "").toLowerCase();
        const service = (emp.service || "").toLowerCase();
        return name.includes(q) || service.includes(q);
      });
    },
    selectedEmployeePending() {
      return this.selectedEmployeeCongeListe.filter(c => c.statut == 0 || c.statut == 4);
    },
    selectedEmployeeHistory() {
      return this.selectedEmployeeCongeListe.filter(c => c.statut > 0 && c.statut != 4);
    },
    filteredHistoryForExport() {
      return this.filterByPeriod(this.selectedEmployeeHistory);
    },
  },
  methods: {
    employeeFirstName(emp) {
      return (emp.user_name || "").split(" ")[0] || "—";
    },
    employeeLastName(emp) {
      const parts = (emp.user_name || "").split(" ");
      return parts.slice(1).join(" ").toUpperCase() || "";
    },
    employeeInitials(emp) {
      return (emp.user_name || "")
        .split(" ")
        .map(w => w[0])
        .join("")
        .toUpperCase()
        .slice(0, 2) || "?";
    },
    employeeColorIndex(emp) {
      const key = emp.service || emp.user_name || "";
      let h = 0;
      for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) & 0xffff;
      return h % COLOR_PALETTE.length;
    },
    employeeColor(emp) { return COLOR_PALETTE[this.employeeColorIndex(emp)]; },
    employeeColorDark(emp) { return COLOR_DARK[this.employeeColorIndex(emp)]; },
    employeePendingCount(emp) {
      return this.pendingCounts[emp.user_id] || 0;
    },
    fetchAllPendingCounts(users) {
      let that = this;
      users.forEach(emp => {
        engine.get_conge_by_user_id(emp.user_id, function (data) {
          if (data.code == 0) {
            const count = data.data.data.data
              .map(v => v.fieldData)
              .filter(c => c.statut == 0).length;
            that.pendingCounts = { ...that.pendingCounts, [emp.user_id]: count };
          }
        });
      });
    },
    formatHireDate(emp) {
      const ts = parseInt(emp.date_embauche_timestamp);
      if (!ts) return "—";
      return new Date(ts * 1000).toLocaleDateString("fr-FR", { day: "2-digit", month: "long", year: "numeric" });
    },
    openEmployee(emp) {
      console.log("openEmployee", emp);

      this.selectedEmployee = emp;
      this.selectedEmployeeCongeListe = [];
      this.selectedEmployeeSoldeListe = [];
      this.showEmployeeDialog = true;
      let that = this;
      engine.get_conge_by_user_id(emp.user_id, function (data) {
        if (data.code == 0) {
          that.selectedEmployeeCongeListe = data.data.data.data.map(val => ({
            ...val.fieldData,
            _recordId: val.recordId,
          }));
        }
      });
      engine.get_solde_by_user_id(emp.user_id, function (data) {
        if (data.code == 0) {
          that.selectedEmployeeSoldeListe = data.data.data.data.map(val => ({ ...val.fieldData, _recordId: val.recordId }));
        }
      });
    },
    openValidationModal(request) {
      this.selectedRequest = request;
      this.adminDeleteMotif = '';
      this.showValidationModal = true;
      this.isUpdating = false;
    },
    cancelCancelRequest(selectedRequest) {
      let that = this
      this.isUpdating = true;
      engine.run_conge_function('demande.accepter', { "id_demande": selectedRequest.id_demande }, function (data) {
        that.isUpdating = false;
        that.showValidationModal = false;
        if (data.code == 0) {
          that.get_basic_data()
          that.openEmployee(that.selectedEmployee)
          that.snackbar = {
            color: 'green',
            value: true,
            msg: 'Modification enregistrée'
          }
        } else {
          that.snackbar = {
            color: 'red',
            value: true,
            msg: 'Une erreur est survenue'
          }
        }
      })
    },
    cancelConge(selectedRequest) {
      let that = this
      this.isUpdating = true;
      engine.run_conge_function('demande.accepter', { "id_demande": selectedRequest.id_demande }, function (data) {
        that.isUpdating = false;
        that.showValidationModal = false;
        if (data.code == 0) {
          that.get_basic_data()
          that.openEmployee(that.selectedEmployee)
          that.snackbar = {
            color: 'green',
            value: true,
            msg: 'Modification enregistrée'
          }
        } else {
          that.snackbar = {
            color: 'red',
            value: true,
            msg: 'Une erreur est survenue'
          }
        }
      })
    },
    deleteRequest(selectedRequest) {
      let that = this
      this.isUpdating = true;
      engine.run_conge_function('demande.refuser', { "id_demande": selectedRequest.id_demande }, function (data) {
        that.isUpdating = false;
        that.showValidationModal = false;
        if (data.code == 0) {
          that.get_basic_data()
          that.openEmployee(that.selectedEmployee)
          that.snackbar = {
            color: 'green',
            value: true,
            msg: 'Modification enregistrée'
          }
        } else {
          that.snackbar = {
