    openSoldeEdit(s) {
      this.editingSoldeType = s.id_conge_type;
      // CP
      this.editSoldeValues = {
        cp_acquis_n: s.cp_acquis_n || 0,
        cp_acquis_n_1: s.cp_acquis_n_1 || 0,
        cp_reserves_n: s.cp_reserves_n || 0,
        cp_reserves_n_1: s.cp_reserves_n_1 || 0,
        cp_solde_n: s.cp_solde_n || 0,
        cp_solde_n_1: s.cp_solde_n_1 || 0,
        // autres types
        solde_initial: s.solde_initial || 0,
        solde_pris: s.solde_pris || 0,
        solde_disponible: s.solde_disponible || 0,
      };
    },
    cancelSoldeEdit() {
      this.editingSoldeType = null;
      this.editSoldeValues = {};
    },
    saveSoldeEdit(s) {
      if (!s._recordId) return;
      this.isSavingSolde = true;
      let that = this;
      // Champs à sauvegarder selon le type
      let fields = s.id_conge_type === 'CP'
        ? {
            cp_acquis_n: this.editSoldeValues.cp_acquis_n,
            cp_acquis_n_1: this.editSoldeValues.cp_acquis_n_1,
            cp_reserves_n: this.editSoldeValues.cp_reserves_n,
            cp_reserves_n_1: this.editSoldeValues.cp_reserves_n_1,
            cp_solde_n: this.editSoldeValues.cp_solde_n,
            cp_solde_n_1: this.editSoldeValues.cp_solde_n_1,
          }
        : {
            solde_initial: this.editSoldeValues.solde_initial,
            solde_pris: this.editSoldeValues.solde_pris,
            solde_disponible: this.editSoldeValues.solde_disponible,
          };
      engine.update_solde(s._recordId, fields, function () {
        that.isSavingSolde = false;
        that.editingSoldeType = null;
        that.editSoldeValues = {};
        // Recharger les soldes de l'employé
        engine.get_solde_by_user_id(that.selectedEmployee.user_id, function (data) {
          if (data.code == 0) {
            that.selectedEmployeeSoldeListe = data.data.data.data.map(val => ({ ...val.fieldData, _recordId: val.recordId }));
          }
        });
      });
    },
    getSoldeColor(solde) {
      const colorMap = {
        red: '#e53935', blue: '#3f51b5', green: '#43a047',
        orange: '#fb8c00', yellow: '#f9a825', purple: '#9c27b0',
        gray: '#757575', grey: '#757575', pink: '#e91e63',
        teal: '#00838f', cyan: '#00acc1', indigo: '#3f51b5',
      };
      const found = this.congeTypes.find(t => t.id_conge_type === solde.id_conge_type);
      if (!found) return '#3f51b5';
      return colorMap[found.color] || found.color || '#3f51b5';
    },
    getTypeName(id) {
      const found = this.congeTypes.find(t => t.id_conge_type === id);
      return found ? found.libelle : id || "—";
    },
    getTypeColor(id) {
      const colorMap = {
        red: '#e53935', blue: '#3f51b5', green: '#43a047',
        orange: '#fb8c00', yellow: '#f9a825', purple: '#9c27b0',
        gray: '#757575', grey: '#757575', pink: '#e91e63',
        teal: '#00838f', cyan: '#00acc1', indigo: '#3f51b5',
      };
      const found = this.congeTypes.find(t => t.id_conge_type === id);
      if (!found) return '#757575';
      return colorMap[found.color] || found.color || '#757575';
    },
    formatDate(ts) {
      if (!ts) return "—";
      return new Date(parseInt(ts) * 1).toLocaleDateString("fr-FR", {
        day: "2-digit", month: "2-digit", year: "numeric",
      });
    },
    parseMotif(commentaire) {
      if (!commentaire) return "—";
      try {
        const parsed = JSON.parse(commentaire);
        if (Array.isArray(parsed) && parsed[0]?.user) return parsed[0].user || "—";
      } catch {
        return commentaire;
      }
      return commentaire;
    },
    adminWorkingDays() {
      const { dateDebut, dateFin } = this.adminForm;
      if (!dateDebut || !dateFin || dateFin < dateDebut) return 0;
      let count = 0;
      const cur = new Date(dateDebut);
      const end = new Date(dateFin);
      while (cur <= end) {
        const d = cur.getDay();
        if (d !== 0 && d !== 6) count++;
        cur.setDate(cur.getDate() + 1);
      }
      return count;
    },
    updateAdminNbrJours() {
      this.$nextTick(() => {
        this.adminForm.nbrJours = this.adminWorkingDays() || null;
      });
    },
    // Arrondit au demi-jour le plus proche (0.5), accepte la virgule ou le point
    roundHalf(v) {
      const n = parseFloat(String(v).replace(',', '.'));
      if (isNaN(n) || n <= 0) return null;
      return Math.round(n * 2) / 2;
    },
    closeNewRequestForm() {
      this.showNewRequestDialog = false;
      this.$nextTick(() => {
        this.adminForm = { type: null, dateDebut: null, dateFin: null, nbrJours: null, motif: '' };
        this.adminDateDebutError = '';
        this.adminDateFinError = '';
        this.$refs.adminRequestForm?.reset();
      });
    },
    async submitAdminRequest() {
      this.adminDateDebutError = '';
      this.adminDateFinError = '';
      if (!this.adminForm.dateDebut) this.adminDateDebutError = 'Champ requis';
      if (!this.adminForm.dateFin) this.adminDateFinError = 'Champ requis';
      else if (this.adminForm.dateDebut && this.adminForm.dateFin < this.adminForm.dateDebut)
        this.adminDateFinError = 'Doit être après le début';
      if (this.adminDateDebutError || this.adminDateFinError) return;

      const { valid } = await this.$refs.adminRequestForm.validate();
      if (!valid) return;

      this.isSubmittingAdmin = true;
      let that = this;
      const payload = {
        statut: 0,
        id_conge_type: this.adminForm.type,
        user_id: this.selectedEmployee.user_id,
        debut_timestamp: parseInt(moment(this.adminForm.dateDebut).format('x')),
        fin_timestamp: parseInt(moment(this.adminForm.dateFin).format('x')),
        commentaire: JSON.stringify([{ user: this.adminForm.motif }]),
        nbr_days: this.roundHalf(this.adminForm.nbrJours) ?? this.adminWorkingDays(),
      };

      engine.create_demande_conge(payload, function () {
        that.isSubmittingAdmin = false;
        that.closeNewRequestForm();
        // Recharger les congés de l'employé
        engine.get_conge_by_user_id(that.selectedEmployee.user_id, function (data) {
          if (data.code == 0) {
            that.selectedEmployeeCongeListe = data.data.data.data.map(val => ({
              ...val.fieldData,
              _recordId: val.recordId,
            }));
          }
        });
      });
    },
    async doGlobalExport() {
      this.isGlobalExporting = true;

      // Récupérer les congés de tous les employés en parallèle
      const results = await Promise.all(
        this.allUsers.map(user =>
          new Promise(resolve => {
            engine.get_conge_by_user_id(user.user_id, data => {
              if (data.code == 0) {
                resolve({ user, conges: data.data.data.data.map(v => v.fieldData) });
              } else {
                resolve({ user, conges: [] });
              }
            });
          })
        )
      );

      // Filtrer : validées (statut == 1) + période
      const now = new Date();
      let startDate = null;
      let endDate = null;
      if (this.globalExportPeriod === 'current') {
        startDate = new Date(now.getFullYear(), now.getMonth(), 1);
        endDate = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
      } else if (this.globalExportPeriod === 'previous') {
        startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        endDate = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);
      } else if (this.globalExportPeriod === 'custom') {
        startDate = this.globalExportDateFrom ? new Date(this.globalExportDateFrom) : null;
        endDate = this.globalExportDateTo ? new Date(this.globalExportDateTo + 'T23:59:59') : null;
      }

      const rows = [];
      results.forEach(({ user, conges }) => {
        conges
          .filter(c => {
            if (c.statut != 1) return false;
            const d = new Date(parseInt(c.debut_timestamp));
            if (startDate && d < startDate) return false;
            if (endDate && d > endDate) return false;
            return true;
          })
          .forEach(c => {
            rows.push({
              'Employé': user.user_name || '—',
              'Service': user.service || '—',
              'Type': this.getTypeName(c.id_conge_type),
              'Date début': this.formatDate(c.debut_timestamp),
              'Date fin': this.formatDate(c.fin_timestamp),
              'Jours': c.nbr_days || '—',
              'Motif': this.parseMotif(c.commentaire),
            });
          });
      });

      // Trier par employé puis par date de début
      rows.sort((a, b) => a['Employé'].localeCompare(b['Employé']) || a['Date début'].localeCompare(b['Date début']));

      const ws = XLSX.utils.json_to_sheet(rows);
      ws['!cols'] = [{ wch: 24 }, { wch: 18 }, { wch: 22 }, { wch: 14 }, { wch: 14 }, { wch: 8 }, { wch: 36 }];

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'Congés validés');

      const periodLabel = this.globalExportPeriod === 'current' ? moment().format('YYYY-MM')
        : this.globalExportPeriod === 'previous' ? moment().subtract(1, 'month').format('YYYY-MM')
          : this.globalExportPeriod === 'custom' ? `${this.globalExportDateFrom || ''}_${this.globalExportDateTo || ''}`
            : 'complet';

      const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
      saveAs(new Blob([wbout], { type: 'application/octet-stream' }),
        `conges_valides_tous_employes_${periodLabel}.xlsx`);

      this.isGlobalExporting = false;
      this.showGlobalExportDialog = false;
    },
    openAdminDeleteDialog(item) {
      this.requestToAdminDelete = item;
      this.showAdminDeleteDialog = true;
    },
    confirmAdminDelete() {
      if (!this.requestToAdminDelete?._recordId) return;
      this.isDeletingAdmin = true;
      let that = this;
      engine.update_conge_statut(this.requestToAdminDelete._recordId, 5, function () {
        that.isDeletingAdmin = false;
        that.showAdminDeleteDialog = false;
        that.requestToAdminDelete = null;
        engine.get_conge_by_user_id(that.selectedEmployee.user_id, function (data) {
          if (data.code == 0) {
            that.selectedEmployeeCongeListe = data.data.data.data.map(val => ({
              ...val.fieldData,
              _recordId: val.recordId,
            }));
          }
        });
      });
    },
    filterByPeriod(items) {
      const now = new Date();
      let startDate = null;
      let endDate = null;
      if (this.exportPeriod === 'current') {
        startDate = new Date(now.getFullYear(), now.getMonth(), 1);
        endDate = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
      } else if (this.exportPeriod === 'previous') {
        startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        endDate = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);
      } else if (this.exportPeriod === 'custom') {
        startDate = this.exportDateFrom ? new Date(this.exportDateFrom) : null;
        endDate = this.exportDateTo ? new Date(this.exportDateTo + 'T23:59:59') : null;
      } else {
        return items;
      }
      return items.filter(item => {
        const d = new Date(parseInt(item.debut_timestamp));
        if (startDate && d < startDate) return false;
        if (endDate && d > endDate) return false;
        return true;
      });
    },
    doExportExcel() {
      const statusLabel = (statut) => {
        if (statut == 1) return 'Validée';
        if (statut == 2) return 'Refusée';
        return 'En attente';
      };

      const employeeName = this.selectedEmployee?.user_name || 'export';

      const rows = this.filteredHistoryForExport.map((item) => ({
        'Type': this.getTypeName(item.id_conge_type),
        'Date début': this.formatDate(item.debut_timestamp),
        'Date fin': this.formatDate(item.fin_timestamp),
        'Jours': item.nbr_days || '—',
        'Motif': this.parseMotif(item.commentaire),
        'Statut': statusLabel(item.statut),
      }));

      const ws = XLSX.utils.json_to_sheet(rows);
      ws['!cols'] = [{ wch: 22 }, { wch: 14 }, { wch: 14 }, { wch: 8 }, { wch: 36 }, { wch: 12 }];

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'Historique');

      const periodLabel = this.exportPeriod === 'current' ? moment().format('YYYY-MM')
        : this.exportPeriod === 'previous' ? moment().subtract(1, 'month').format('YYYY-MM')
          : this.exportPeriod === 'custom' ? `${this.exportDateFrom || ''}_${this.exportDateTo || ''}`
            : 'complet';
      const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
      const fileName = `historique_conges_${employeeName}_${periodLabel}.xlsx`;
      saveAs(new Blob([wbout], { type: 'application/octet-stream' }), fileName);
      this.showExportDialog = false;
    },
  },
};
